<?php require '../config.php';require_admin();$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['pname']??'');$cat=(int)($_POST['category_id']??0);$price=$_POST['price']??'';$pic='';
if($name===''||!is_numeric($price)||$price<0||!in_array($cat,array_column($cats,'id'))) $error='Enter valid product details.';
elseif(!isset($_FILES['picture'])||$_FILES['picture']['error']!==UPLOAD_ERR_OK)$error='Please select a product image.';
else{$f=$_FILES['picture'];$info=@getimagesize($f['tmp_name']);$mime=$info['mime']??'';$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!$info||!isset($types[$mime])||$f['size']>4*1024*1024)$error='Use JPG, PNG or WebP image up to 4 MB.';
else{$dir=__DIR__.'/../uploads';if(!is_dir($dir))mkdir($dir,0755,true);$filename=bin2hex(random_bytes(12)).'.'.$types[$mime];$dest=$dir.'/'.$filename;
if(!extension_loaded('gd'))$error='PHP GD extension is not enabled. Enable GD in php.ini and restart Apache.';
else{$src=match($mime){'image/jpeg'=>@imagecreatefromjpeg($f['tmp_name']),'image/png'=>@imagecreatefrompng($f['tmp_name']),'image/webp'=>@imagecreatefromwebp($f['tmp_name'])};if(!$src)$error='Unable to read image.';else{$w=imagesx($src);$h=imagesy($src);$scale=min(1,800/max($w,$h));$nw=max(1,(int)($w*$scale));$nh=max(1,(int)($h*$scale));$out=imagecreatetruecolor($nw,$nh);if($mime==='image/png'||$mime==='image/webp'){imagealphablending($out,false);imagesavealpha($out,true);$transparent=imagecolorallocatealpha($out,0,0,0,127);imagefilledrectangle($out,0,0,$nw,$nh,$transparent);}imagecopyresampled($out,$src,0,0,0,0,$nw,$nh,$w,$h);$ok=match($mime){'image/jpeg'=>imagejpeg($out,$dest,85),'image/png'=>imagepng($out,$dest,6),'image/webp'=>imagewebp($out,$dest,85)};imagedestroy($src);imagedestroy($out);if(!$ok)$error='Could not save resized image.';else{$pic='uploads/'.$filename;try{$s=$pdo->prepare("INSERT INTO products(category_id,pname,price,picture) VALUES(?,?,?,?)");$s->execute([$cat,$name,$price,$pic]);header('Location: products.php');exit;}catch(PDOException $e){@unlink($dest);$error='Could not save product.';}}}}}}}
?><!doctype html><html><head><meta charset="utf-8"><title>Add product</title><link rel="stylesheet" href="../assets/style.css"></head><body><main><h1>Add Product</h1><p class="error"><?=h($error)?></p><form method="post" enctype="multipart/form-data"><label>Product name<input name="pname" required></label><label>Category<select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select></label><label>Price<input type="number" name="price" min="0" step="0.01" required></label><label>Picture (JPG, PNG, WebP; max 4 MB)<input type="file" name="picture" accept="image/jpeg,image/png,image/webp" required></label><button>Add product</button></form><a href="products.php">Back</a></main></body></html>